const ee = require('@google/earthengine');
const privateKey = require('../auth_keys/test-project-473922-29f05d49bed7');

async function runAnalysis() {
  // 1. Define geometry: 50 mile radius around the point
  const lat = 34.498828;
  const lon = -112.246886;
  const radiusMiles = 50;
  const radiusMeters = radiusMiles * 1609.34; // Convert miles to meters
  const point = ee.Geometry.Point([lon, lat]);
  const aoi = point.buffer(radiusMeters);

  // 2. Define date range: June 20, 2017 to June 30, 2017
  const startDate = '2017-06-20';
  const endDate = '2017-06-30';

  // 3. Load MODIS Thermal Anomalies (FIRMS data via MCD14ML)
  // This dataset contains active fire detections
  const firmsCollection = ee.ImageCollection('MODIS/006/MCD14ML')
    .filterDate(startDate, endDate)
    .filterBounds(aoi);

  const firmsSize = await firmsCollection.size().getInfo();
  print(`MODIS FIRMS Images: ${firmsSize}`);

  if (firmsSize === 0) {
    // Fallback to MODIS Burned Area MCD64A1
    const burnedAreaCollection = ee.ImageCollection('MODIS/006/MCD64A1')
      .filterDate(startDate, endDate)
      .filterBounds(aoi);

    const baSize = await burnedAreaCollection.size().getInfo();
    print(`MODIS Burned Area Images: ${baSize}`);

    if (baSize === 0) {
      print('No fire data available for the date/location.');
      print('C1');
      return;
    }

    // Process burned area data
    const burnedAreaImg = burnedAreaCollection.first();
    const burnDate = burnedAreaImg.select('BurnDate');

    const validPixels = await burnDate.reduceRegion({
      reducer: ee.Reducer.count(),
      geometry: aoi,
      scale: 500,
      maxPixels: 1e9
    }).get('BurnDate').getInfo();

    print(`Burned Area Valid Pixels: ${validPixels}`);

    if (validPixels === 0 || validPixels === null) {
      print('No valid burned area pixels detected.');
      print('B');
      return;
    }

    // Count pixels with burn dates in June 2017
    const firePixels = await burnDate
      .gt(0) // Burn date > 0 indicates a fire
      .reduceRegion({
        reducer: ee.Reducer.sum(),
        geometry: aoi,
        scale: 500,
        maxPixels: 1e9
      })
      .get('BurnDate').getInfo();

    print(`Fire Pixels (Burned Area): ${firePixels}`);

    if (firePixels === null || firePixels === 0) {
      print('No fires detected in burned area data.');
      print('B');
    } else {
      print(`Fires detected: ${firePixels} pixels`);
      print('A');
    }
  } else {
    // Process FIRMS active fire data
    const firmsImg = firmsCollection.first();
    const confidence = firmsImg.select('confidence');

    // Count high-confidence fire detections (confidence > 50)
    const firePixels = await confidence
      .gt(50)
      .reduceRegion({
        reducer: ee.Reducer.sum(),
        geometry: aoi,
        scale: 1000,
        maxPixels: 1e9
      })
      .get('confidence').getInfo();

    print(`FIRMS High-Confidence Fire Pixels: ${firePixels}`);

    if (firePixels === null || firePixels === 0) {
      print('No active fires detected (FIRMS).');
      print('B');
    } else {
      print(`Active fires detected: ${firePixels} pixels`);
      print('A');
    }
  }
}

async function initEE() {
  await new Promise((resolve, reject) => {
    ee.data.authenticateViaPrivateKey(privateKey, resolve, reject);
  });
  await new Promise((resolve, reject) => {
    ee.initialize(null, null, resolve, reject);
  });
  await runAnalysis();
}

initEE();
